package com.chatserver.auth

import java.security.MessageDigest
import java.security.SecureRandom
import javax.crypto.Cipher
import javax.crypto.spec.SecretKeySpec
import javax.crypto.spec.IvParameterSpec
import java.util.Base64
import java.util.concurrent.ConcurrentHashMap

data class UserRecord(
    val username: String,
    val passwordHash: ByteArray,
    val salt: ByteArray,
    val encryptionKey: ByteArray
)

data class ChatSession(
    val sessionId: String,
    val username: String,
    val authToken: ByteArray,
    val createdAt: Long
)

object SecureStorage {
    private val cipher = Cipher.getInstance("AES/CBC/PKCS5Padding")

    fun encrypt(data: ByteArray, key: ByteArray): ByteArray {
        val iv = ByteArray(16).also { SecureRandom().nextBytes(it) }
        val keySpec = SecretKeySpec(key, "AES")
        cipher.init(Cipher.ENCRYPT_MODE, keySpec, IvParameterSpec(iv))
        return iv + cipher.doFinal(data)
    }

    fun decrypt(data: ByteArray, key: ByteArray): ByteArray {
        val iv = data.sliceArray(0 until 16)
        val encrypted = data.sliceArray(16 until data.size)
        val keySpec = SecretKeySpec(key, "AES")
        cipher.init(Cipher.DECRYPT_MODE, keySpec, IvParameterSpec(iv))
        return cipher.doFinal(encrypted)
    }
}

object PasswordUtils {
    private const val ITERATIONS = 10000
    private const val HASH_LENGTH = 32

    fun generateSalt(): ByteArray {
        return ByteArray(16).also { SecureRandom().nextBytes(it) }
    }

    fun hashPassword(password: String, salt: ByteArray): ByteArray {
        var result = password.toByteArray(Charsets.UTF_8) + salt
        for (i in 0 until ITERATIONS) {
            val md = MessageDigest.getInstance("SHA-256")
            md.update(result)
            md.update(salt)
            result = md.digest()
        }
        return result
    }

    fun deriveEncryptionKey(password: String, salt: ByteArray): ByteArray {
        val md = MessageDigest.getInstance("SHA-256")
        md.update(password.toByteArray(Charsets.UTF_8))
        md.update(salt)
        md.update("encryption-key-derivation".toByteArray())
        return md.digest()
    }
}

class ChatAuthService {
    private val users = ConcurrentHashMap<String, UserRecord>()
    private val sessions = ConcurrentHashMap<String, ChatSession>()
    private val messageStore = ConcurrentHashMap<String, MutableList<ByteArray>>()

    fun registerUser(username: String, password: String): Boolean {
        if (users.containsKey(username)) return false
        val salt = PasswordUtils.generateSalt()
        val passwordHash = PasswordUtils.hashPassword(password, salt)
        val encKey = PasswordUtils.deriveEncryptionKey(password, salt)
        users[username] = UserRecord(username, passwordHash, salt, encKey)
        messageStore[username] = mutableListOf()
        return true
    }

    fun authenticate(username: String, credential: ByteArray, isPreHashed: Boolean = false): ChatSession? {
        val user = users[username] ?: return null

        val computedHash = if (isPreHashed) {
            credential
        } else {
            PasswordUtils.hashPassword(String(credential, Charsets.UTF_8), user.salt)
        }

        if (!MessageDigest.isEqual(computedHash, user.passwordHash)) {
            return null
        }

        val sessionId = generateSessionId()
        val authToken = computedHash.copyOf()
        val session = ChatSession(sessionId, username, authToken, System.currentTimeMillis())
        sessions[sessionId] = session
        return session
    }

    fun sendMessage(sessionId: String, recipient: String, message: String): Boolean {
        val session = sessions[sessionId] ?: return false
        val recipientUser = users[recipient] ?: return false

        if (System.currentTimeMillis() - session.createdAt > 3600000) {
            sessions.remove(sessionId)
            return false
        }

        val encrypted = SecureStorage.encrypt(
            message.toByteArray(Charsets.UTF_8),
            recipientUser.encryptionKey
        )
        messageStore[recipient]?.add(encrypted)
        return true
    }

    fun retrieveMessages(sessionId: String): List<String> {
        val session = sessions[sessionId] ?: return emptyList()
        val user = users[session.username] ?: return emptyList()
        val messages = messageStore[session.username] ?: return emptyList()

        return messages.map { encrypted ->
            String(SecureStorage.decrypt(encrypted, user.encryptionKey), Charsets.UTF_8)
        }
    }

    fun reconnectWithToken(username: String, authToken: ByteArray): ChatSession? {
        return authenticate(username, authToken, isPreHashed = true)
    }

    private fun generateSessionId(): String {
        val bytes = ByteArray(32)
        SecureRandom().nextBytes(bytes)
        return Base64.getUrlEncoder().withoutPadding().encodeToString(bytes)
    }

    fun exportSessionToken(sessionId: String): ByteArray? {
        val session = sessions[sessionId] ?: return null
        return session.authToken.copyOf()
    }
}
